function login() {
  let une = source.getLoginInfoMap().get("账号")
  let pwd = source.getLoginInfoMap().get("密码")
  if (une && pwd) {
    let body = String('username=' + une + '&password=' + pwd + '&usecookie=315360000&action=login&submit=')
    let url = 'https://tw.linovelib.com/login.php'
    ajax(url)
    let ck = java.post(url, body, {
    	 "Content-Type": "application/x-www-form-urlencoded",
    	 "User-Agent": java.getWebViewUA()}).cookies()
    let header = JSON.stringify({
      "Cookie": String(ck).match(/\{(.*?)\}/)[1].replace(/,/g, ';')
    })
    source.putLoginHeader(header)
  }
}

