var regex=/第\d*.(\d+)页.当前\d*条.页/;
//正则匹配页数
var page=src.match(regex);
page=page?page[1]:"";
var next=result?result[0]:"";
next=String(next);
var url=[next];
for(i=2;i<=page;i++){
	url.push(next.replace(/p\d+/,"p"+i))
	}
url;

